#!/usr/bin/env node
'use strict';

/**
 * check-advertised-mcp-tools.js
 *
 * Detects "advertised but missing" MCP tools: reads the Claude/OpenCode MCP
 * configs generated by generate-agent-mcp-config.js and confirms the script
 * file behind every local (stdio) `node <path>` server entry actually exists
 * in this image. A server can be *listed* in tools/list yet be completely
 * unusable if its script was never COPYed into Dockerfile.engineering — that
 * exact gap shipped once for builder-manager-mcp.js (advertised via
 * generate-agent-mcp-config.js, missing from the image) and is the reason
 * this check exists.
 *
 * Run after generate-agent-mcp-config.js (e.g. at the end of
 * engineering-entrypoint.sh, or by hand inside a live pod for diagnosis).
 * Exits 1 and lists the offending server(s) if anything is missing; exits 0
 * (printing what it found) otherwise. Safe to run with no generated config
 * present (e.g. outside a k3s pod) — it just reports nothing to check.
 */

const fs = require('fs');
const os = require('os');
const path = require('path');

const HOME = os.homedir();

function readJson(filePath) {
  if (!fs.existsSync(filePath)) return null;
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch (err) {
    console.error(`[check-advertised-mcp-tools] WARN: could not parse ${filePath} (${err.message})`);
    return null;
  }
}

function fromClaudeConfig(config) {
  const entries = [];
  for (const [name, server] of Object.entries(config.mcpServers || {})) {
    if (server.command === 'node' && Array.isArray(server.args) && server.args[0]) {
      entries.push({ name, scriptPath: server.args[0], source: '.claude.json' });
    }
  }
  return entries;
}

function fromOpencodeConfig(config) {
  const entries = [];
  for (const [name, server] of Object.entries(config.mcp || {})) {
    if (server.type === 'local' && Array.isArray(server.command) && server.command[0] === 'node' && server.command[1]) {
      entries.push({ name, scriptPath: server.command[1], source: 'opencode.json' });
    }
  }
  return entries;
}

function main() {
  const claudeConfig = readJson(path.join(HOME, '.claude.json'));
  const opencodeConfig = readJson(path.join(HOME, '.config', 'opencode', 'opencode.json'));

  const entries = [
    ...(claudeConfig ? fromClaudeConfig(claudeConfig) : []),
    ...(opencodeConfig ? fromOpencodeConfig(opencodeConfig) : []),
  ];

  if (entries.length === 0) {
    console.log('[check-advertised-mcp-tools] no generated Claude/OpenCode MCP config with local stdio servers found — nothing to check');
    return;
  }

  const missing = [];
  for (const entry of entries) {
    const ok = fs.existsSync(entry.scriptPath);
    console.log(`[check-advertised-mcp-tools] ${ok ? 'OK     ' : 'MISSING'} ${entry.source}: ${entry.name} -> ${entry.scriptPath}`);
    if (!ok) missing.push(entry);
  }

  if (missing.length > 0) {
    console.error(
      `[check-advertised-mcp-tools] FAIL: ${missing.length} advertised tool(s) point at a script this image does not have: ` +
        missing.map((e) => e.name).join(', '),
    );
    process.exitCode = 1;
    return;
  }

  console.log(`[check-advertised-mcp-tools] PASS: all ${entries.length} locally-launched MCP tool(s) have their script present.`);
}

main();
